window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f1f3721a821673b6"]={"versions": [{"id": "FIG-f1f3721a821673b6", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der Metamodellstruktur von nichtflüchtigen Datenschnittstellen (<code>NvDataInterface</code>) innerhalb des AUTOSAR-Software-Component-Templates. Das Diagramm spezifiziert die Spezialisierung von Port-Schnittstellen und deren Zusammensetzung aus Datenprototypen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code> (kursiv, abstrakt): Stereotypisiert als <code>«atpType»</code>, spezialisiert <code>ARElement</code>. Besitzt das Attribut <code>+ isService :Boolean</code>.</li>\n<li><code>NvDataInterface</code>: Stereotypisiert als <code>«atpType»</code>, erbt via Generalisierung von <code>PortInterface</code>.</li>\n<li><code>DataPrototype</code> (kursiv, abstrakt): Übergeordnete Abstraktion für Datenprototypen.</li>\n<li><code>DataElementPrototype</code>: Stereotypisiert als <code>«atpPrototype»</code>, spezialisiert <code>DataPrototype</code>. Besitzt das Attribut <code>+ isQueued :Boolean</code>.</li>\n<li>Beziehung: <code>NvDataInterface</code> aggregiert <code>DataElementPrototype</code> über eine gerichtete Komposition mit der Zielrolle <code>+nvData</code> und der Multiplizität <code>1..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm ohne Darstellung von Laufzeit- oder Sequenzabläufen. Die Komposition definiert, dass ein <code>NvDataInterface</code> bei der Modellierung mindestens ein <code>DataElementPrototype</code> instanziieren muss. Über das Flag <code>isQueued</code> wird angegeben, ob der Datenaustausch gepuffert (queued) oder ungepuffert erfolgt; <code>isService</code> deklariert den Schnittstellencharakter als Basis- oder Plattformdienst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Generatoren müssen sicherstellen, dass jede nichtflüchtige Schnittstelle mindestens ein Datenelement besitzt (<code>1..*</code>). Da <code>NvDataInterface</code> und <code>DataElementPrototype</code> als AUTOSAR-Typ bzw. AUTOSAR-Prototyp typisiert sind, gelten die allgemeinen Konsistenzregeln für Typ-Prototyp-Muster und Paketierung als <code>ARElement</code>.</p>"}, {"id": "FIG-a6f9ea1987cb24d3", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für nichtflüchtige Datenschnittstellen (<code>NvDataInterface</code>) und deren Vererbungshierarchie im AUTOSAR-Software-Component-Template. Das Diagramm ordnet Schnittstellen und Datenprototypen in die Blueprint- und Prototyping-Konzepte des Metamodells ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code> (kursiv, abstrakt): Zugeordnete Meta-Eigenschaften <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>. Attribute: <code>+ isService: Boolean</code> und <code>+ serviceKind: ServiceProviderEnum [0..1]</code>.</li>\n<li><code>DataInterface</code> (kursiv, abstrakt): Spezialisiert <code>PortInterface</code> via Generalisierung.</li>\n<li><code>NvDataInterface</code>: Spezialisiert <code>DataInterface</code> via Generalisierung.</li>\n<li><code>DataPrototype</code> (kursiv, abstrakt): Oberklasse im Prototypen-Zweig.</li>\n<li><code>AutosarDataPrototype</code> (kursiv, abstrakt): Spezialisiert <code>DataPrototype</code> via Generalisierung.</li>\n<li><code>VariableDataPrototype</code>: Spezialisiert <code>AutosarDataPrototype</code> via Generalisierung. Enthält keine eigenen Attribute.</li>\n<li>Beziehung: <code>NvDataInterface</code> enthält <code>VariableDataPrototype</code> über eine Komposition mit Quellrolle <code>+interface</code> und Zielrolle <code>+nvData</code> bei einer Multiplizität von <code>1..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen. Die Struktur legt fest, dass ein <code>NvDataInterface</code> Träger von mindestens einem veränderlichen Datenprototypen (<code>VariableDataPrototype</code>) ist. Über <code>serviceKind</code> kann optional die Art des Dienstanbieters klassifiziert werden, sofern <code>isService</code> aktiv ist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>NvDataInterface</code> muss mindestens einen <code>VariableDataPrototype</code> enthalten (<code>1..*</code>). Da die Elemente <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> unterstützen, können Schnittstellenmuster als Blueprints vorgegeben werden. Implementierungen greifen über die allgemeine <code>DataInterface</code>-Hierarchie auf die Datenelemente zu; Warteschlangen-Semantiken (<code>isQueued</code>) sind auf Metamodellebene des Prototyps hier nicht mehr modelliert.</p>"}, {"id": "FIG-c49422437b24cbad", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für nichtflüchtige Datenschnittstellen (<code>NvDataInterface</code>) und deren Vererbungshierarchie im AUTOSAR-Software-Component-Template. Das Diagramm ordnet Schnittstellen und Datenprototypen in die Blueprint- und Prototyping-Konzepte des Metamodells ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code> (kursiv, abstrakt): Zugeordnete Meta-Eigenschaften <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>. Attribute: <code>+ isService :Boolean</code> und <code>+ serviceKind :ServiceProviderEnum [0..1]</code>.</li>\n<li><code>DataInterface</code> (kursiv, abstrakt): Spezialisiert <code>PortInterface</code> via Generalisierung.</li>\n<li><code>NvDataInterface</code>: Spezialisiert <code>DataInterface</code> via Generalisierung.</li>\n<li><code>DataPrototype</code> (kursiv, abstrakt): Oberklasse im Prototypen-Zweig.</li>\n<li><code>AutosarDataPrototype</code> (kursiv, abstrakt): Spezialisiert <code>DataPrototype</code> via Generalisierung.</li>\n<li><code>VariableDataPrototype</code>: Spezialisiert <code>AutosarDataPrototype</code> via Generalisierung. Enthält keine eigenen Attribute.</li>\n<li>Beziehung: <code>NvDataInterface</code> enthält <code>VariableDataPrototype</code> über eine gerichtete Komposition mit Zielrolle <code>+nvData</code> bei einer Multiplizität von <code>1..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen. Die Struktur legt fest, dass ein <code>NvDataInterface</code> Träger von mindestens einem veränderlichen Datenprototypen (<code>VariableDataPrototype</code>) ist. Über <code>serviceKind</code> kann optional die Art des Dienstanbieters klassifiziert werden, sofern <code>isService</code> aktiv ist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>NvDataInterface</code> muss mindestens einen <code>VariableDataPrototype</code> enthalten (<code>1..*</code>). Da die Elemente <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> unterstützen, können Schnittstellenmuster als Blueprints vorgegeben werden. Implementierungen greifen über die allgemeine <code>DataInterface</code>-Hierarchie auf die Datenelemente zu; Warteschlangen-Semantiken (<code>isQueued</code>) sind auf Metamodellebene des Prototyps hier nicht mehr modelliert.</p>"}, {"id": "FIG-3e02f5cf79b80ea3", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für nichtflüchtige Datenschnittstellen (<code>NvDataInterface</code>) und deren Vererbungshierarchie im AUTOSAR-Software-Component-Template. Das Diagramm ordnet Schnittstellen und Datenprototypen in die Blueprint- und Prototyping-Konzepte des Metamodells ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code> (kursiv, abstrakt): Zugeordnete Meta-Eigenschaften <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>. Attribute: <code>+ isService :Boolean</code> und <code>+ serviceKind :ServiceProviderEnum [0..1]</code>.</li>\n<li><code>DataInterface</code> (kursiv, abstrakt): Spezialisiert <code>PortInterface</code> via Generalisierung.</li>\n<li><code>NvDataInterface</code>: Spezialisiert <code>DataInterface</code> via Generalisierung.</li>\n<li><code>DataPrototype</code> (kursiv, abstrakt): Oberklasse im Prototypen-Zweig.</li>\n<li><code>AutosarDataPrototype</code> (kursiv, abstrakt): Spezialisiert <code>DataPrototype</code> via Generalisierung.</li>\n<li><code>VariableDataPrototype</code>: Spezialisiert <code>AutosarDataPrototype</code> via Generalisierung. Enthält keine eigenen Attribute.</li>\n<li>Beziehung: <code>NvDataInterface</code> enthält <code>VariableDataPrototype</code> über eine gerichtete Komposition mit Zielrolle <code>+nvData</code> bei einer Multiplizität von <code>1..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen. Die Struktur legt fest, dass ein <code>NvDataInterface</code> Träger von mindestens einem veränderlichen Datenprototypen (<code>VariableDataPrototype</code>) ist. Über <code>serviceKind</code> kann optional die Art des Dienstanbieters klassifiziert werden, sofern <code>isService</code> aktiv ist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>NvDataInterface</code> muss mindestens einen <code>VariableDataPrototype</code> enthalten (<code>1..*</code>). Da die Elemente <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> unterstützen, können Schnittstellenmuster als Blueprints vorgegeben werden. Implementierungen greifen über die allgemeine <code>DataInterface</code>-Hierarchie auf die Datenelemente zu; Warteschlangen-Semantiken (<code>isQueued</code>) sind auf Metamodellebene des Prototyps hier nicht mehr modelliert.</p>"}, {"id": "FIG-7dde9b0b092c1a3a", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für nichtflüchtige Datenschnittstellen (<code>NvDataInterface</code>) und deren Vererbungshierarchie im AUTOSAR-Software-Component-Template. Das Diagramm ordnet Schnittstellen und Datenprototypen in die Blueprint- und Prototyping-Konzepte des Metamodells ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code> (kursiv, abstrakt): Zugeordnete Meta-Eigenschaften <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>. Attribute: <code>+ isService: Boolean</code> und <code>+ serviceKind: ServiceProviderEnum [0..1]</code>.</li>\n<li><code>DataInterface</code> (kursiv, abstrakt): Spezialisiert <code>PortInterface</code> via Generalisierung.</li>\n<li><code>NvDataInterface</code>: Spezialisiert <code>DataInterface</code> via Generalisierung.</li>\n<li><code>DataPrototype</code> (kursiv, abstrakt): Oberklasse im Prototypen-Zweig.</li>\n<li><code>AutosarDataPrototype</code> (kursiv, abstrakt): Spezialisiert <code>DataPrototype</code> via Generalisierung.</li>\n<li><code>VariableDataPrototype</code>: Spezialisiert <code>AutosarDataPrototype</code> via Generalisierung. Enthält keine eigenen Attribute.</li>\n<li>Beziehung: <code>NvDataInterface</code> enthält <code>VariableDataPrototype</code> über eine gerichtete Komposition mit Zielrolle <code>+nvData</code> bei einer Multiplizität von <code>1..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen. Die Struktur legt fest, dass ein <code>NvDataInterface</code> Träger von mindestens einem veränderlichen Datenprototypen (<code>VariableDataPrototype</code>) ist. Über <code>serviceKind</code> kann optional die Art des Dienstanbieters klassifiziert werden, sofern <code>isService</code> aktiv ist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>NvDataInterface</code> muss mindestens einen <code>VariableDataPrototype</code> enthalten (<code>1..*</code>). Da die Elemente <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> unterstützen, können Schnittstellenmuster als Blueprints vorgegeben werden. Implementierungen greifen über die allgemeine <code>DataInterface</code>-Hierarchie auf die Datenelemente zu; Warteschlangen-Semantiken (<code>isQueued</code>) sind auf Metamodellebene des Prototyps hier nicht mehr modelliert.</p>"}, {"id": "FIG-bfcd33e049d9f90f", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für nichtflüchtige Datenschnittstellen (<code>NvDataInterface</code>) und deren Vererbungshierarchie im AUTOSAR-Software-Component-Template. Das Diagramm ordnet Schnittstellen und Datenprototypen in die Blueprint- und Prototyping-Konzepte des Metamodells ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code> (kursiv, abstrakt): Zugeordnete Meta-Eigenschaften <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>. Attribute: <code>+ isService: Boolean</code> und <code>+ serviceKind: ServiceProviderEnum [0..1]</code>.</li>\n<li><code>DataInterface</code> (kursiv, abstrakt): Spezialisiert <code>PortInterface</code> via Generalisierung.</li>\n<li><code>NvDataInterface</code>: Spezialisiert <code>DataInterface</code> via Generalisierung.</li>\n<li><code>DataPrototype</code> (kursiv, abstrakt): Oberklasse im Prototypen-Zweig.</li>\n<li><code>AutosarDataPrototype</code> (kursiv, abstrakt): Spezialisiert <code>DataPrototype</code> via Generalisierung.</li>\n<li><code>VariableDataPrototype</code>: Spezialisiert <code>AutosarDataPrototype</code> via Generalisierung. Enthält keine eigenen Attribute.</li>\n<li>Beziehung: <code>NvDataInterface</code> enthält <code>VariableDataPrototype</code> über eine gerichtete Komposition mit Zielrolle <code>+nvData</code> bei einer Multiplizität von <code>1..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen. Die Struktur legt fest, dass ein <code>NvDataInterface</code> Träger von mindestens einem veränderlichen Datenprototypen (<code>VariableDataPrototype</code>) ist. Über <code>serviceKind</code> kann optional die Art des Dienstanbieters klassifiziert werden, sofern <code>isService</code> aktiv ist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>NvDataInterface</code> muss mindestens einen <code>VariableDataPrototype</code> enthalten (<code>1..*</code>). Da die Elemente <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> unterstützen, können Schnittstellenmuster als Blueprints vorgegeben werden. Implementierungen greifen über die allgemeine <code>DataInterface</code>-Hierarchie auf die Datenelemente zu; Warteschlangen-Semantiken (<code>isQueued</code>) sind auf Metamodellebene des Prototyps hier nicht mehr modelliert.</p>"}, {"id": "FIG-66ad1e66f3cfc62d", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für nichtflüchtige Datenschnittstellen (<code>NvDataInterface</code>) und deren Vererbungshierarchie im AUTOSAR-Software-Component-Template. Das Diagramm ordnet Schnittstellen und Datenprototypen in die Blueprint- und Prototyping-Konzepte des Metamodells ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code> (kursiv, abstrakt): Zugeordnete Meta-Eigenschaften <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>. Attribute: <code>+ isService: Boolean [0..1]</code> und <code>+ serviceKind: ServiceProviderEnum [0..1]</code>.</li>\n<li><code>DataInterface</code> (kursiv, abstrakt): Spezialisiert <code>PortInterface</code> via Generalisierung.</li>\n<li><code>NvDataInterface</code>: Spezialisiert <code>DataInterface</code> via Generalisierung.</li>\n<li><code>DataPrototype</code> (kursiv, abstrakt): Oberklasse im Prototypen-Zweig.</li>\n<li><code>AutosarDataPrototype</code> (kursiv, abstrakt): Spezialisiert <code>DataPrototype</code> via Generalisierung.</li>\n<li><code>VariableDataPrototype</code>: Spezialisiert <code>AutosarDataPrototype</code> via Generalisierung.</li>\n<li>Beziehung: <code>NvDataInterface</code> aggregiert <code>VariableDataPrototype</code> über eine gerichtete Komposition mit Zielrolle <code>+nvData</code> bei einer Multiplizität von <code>0..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen. Die Struktur erlaubt die Definition eines <code>NvDataInterface</code> auch ohne unmittelbare Definition von Datenprototypen zur Entwurfszeit (<code>0..*</code>). Die Attribute <code>isService</code> und <code>serviceKind</code> steuern optional die Dienstzugehörigkeit und den Service-Typ.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Da die Kardinalität von <code>+nvData</code> auf <code>0..*</code> gesenkt wurde, ist die Angabe von <code>VariableDataPrototype</code> in einem <code>NvDataInterface</code> optional; Schnittstellen können leer definiert oder modular erweitert werden. Das Attribut <code>isService</code> besitzt die Multiplizität <code>[0..1]</code>, womit es optional gesetzt werden kann. Generatoren und Validierungswerkzeuge dürfen das Vorhandensein von Nutzdatenfeldern oder Dienstattributen nicht mehr zwingend als Pflichtelement für ein gültiges Schnittstellen-Metamodell voraussetzen.</p>"}], "trans": [{"from": "FIG-f1f3721a821673b6", "to": "FIG-a6f9ea1987cb24d3", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>PortInterface: Stereotyp <code>«atpType»</code> entfällt in der Titelleiste; stattdessen sind die Tags <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code> oben rechts aufgeführt.</li>\n<li>PortInterface: Attribut <code>+ serviceKind: ServiceProviderEnum [0..1]</code> neu eingefügt; Schreibweise von <code>+ isService :Boolean</code> auf <code>+ isService: Boolean</code> angepasst.</li>\n<li>DataInterface: Neue abstrakte Zwischenklasse <code>DataInterface</code> eingefügt, die von <code>PortInterface</code> erbt und von der <code>NvDataInterface</code> ableitet.</li>\n<li>NvDataInterface: Stereotyp <code>«atpType»</code> entfällt.</li>\n<li>DataElementPrototype: Ersetzt durch <code>VariableDataPrototype</code>, das von der abstrakten Klasse <code>AutosarDataPrototype</code> (mit Oberbegriff <code>DataPrototype</code>) erbt; Stereotyp <code>«atpPrototype»</code> entfällt.</li>\n<li>VariableDataPrototype: Attribut <code>+ isQueued :Boolean</code> entfällt.</li>\n<li>Komposition NvDataInterface zu VariableDataPrototype: Rollenbezeichnung auf Quellseite mit <code>+interface</code> beschriftet.</li>\n</ul>"}, {"from": "FIG-a6f9ea1987cb24d3", "to": "FIG-c49422437b24cbad", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Komposition NvDataInterface zu VariableDataPrototype: Rollenbezeichnung <code>+interface</code> am Ende bei NvDataInterface entfernt.</li>\n<li>PortInterface: Leerzeichen vor Doppelpunkt in den Attributen (<code>+ isService :Boolean</code>, <code>+ serviceKind :ServiceProviderEnum [0..1]</code>) wieder eingefügt.</li>\n</ul>"}, {"from": "FIG-c49422437b24cbad", "to": "FIG-3e02f5cf79b80ea3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3e02f5cf79b80ea3", "to": "FIG-7dde9b0b092c1a3a", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>PortInterface: Leerzeichen vor den Doppelpunkten bei Attributen entfernt (<code>+ isService: Boolean</code>, <code>+ serviceKind: ServiceProviderEnum [0..1]</code>).</li>\n</ul>"}, {"from": "FIG-7dde9b0b092c1a3a", "to": "FIG-bfcd33e049d9f90f", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bfcd33e049d9f90f", "to": "FIG-66ad1e66f3cfc62d", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>PortInterface: Multiplizität des Attributs <code>+ isService</code> von implizit <code>[1]</code> auf <code>[0..1]</code> geändert (<code>+ isService: Boolean [0..1]</code>).</li>\n<li>Komposition NvDataInterface zu VariableDataPrototype (<code>+nvData</code>): Untere Multiplizität von <code>1..<em></code> auf <code>0..</em></code> gelockert.</li>\n</ul>"}]};
